  /**
   * Check if the business is closed on a given logical date.
   */
  private async isBusinessClosed(logicalDate: string): Promise<boolean> {
    const count = await this.closureRepository.count({
      where: {
        startDate: LessThanOrEqual(logicalDate),
        endDate: MoreThanOrEqual(logicalDate),
      },
    });
    return count > 0;
  }

